import{_ as a,o as e,c as o,ai as n}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"让 Bot 用自己的邮箱收验证码和订阅，别再占用你的主邮箱","description":"","frontmatter":{"date":"2026-10-20T00:00:00.000Z","title":"让 Bot 用自己的邮箱收验证码和订阅，别再占用你的主邮箱","summary":"Bot 可以申请一个属于自己的邮箱地址。用它注册网站、收验证码、订阅资讯，再用「名字+标签」分流，主邮箱干干净净。","category":"使用技巧","tags":["邮箱","例程","连接器"],"sources":[{"url":"https://x.ai/changelog/bot","author":"Grok Bot Changelog（0.70.2 与 0.71.2）","platform":"官方更新日志"}],"wordCount":468,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"让 Bot 用自己的邮箱收验证码和订阅，别再占用你的主邮箱 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"Bot 可以申请一个属于自己的邮箱地址。用它注册网站、收验证码、订阅资讯，再用「名字+标签」分流，主邮箱干干净净。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/daily/2026-10-20-bot-own-email"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/daily-2026-10-20-bot-own-email-7c728e5d68.png"}],["meta",{"property":"og:image:alt","content":"让 Bot 用自己的邮箱收验证码和订阅，别再占用你的主邮箱 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"让 Bot 用自己的邮箱收验证码和订阅，别再占用你的主邮箱 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"Bot 可以申请一个属于自己的邮箱地址。用它注册网站、收验证码、订阅资讯，再用「名字+标签」分流，主邮箱干干净净。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/daily-2026-10-20-bot-own-email-7c728e5d68.png"}],["meta",{"name":"twitter:image:alt","content":"让 Bot 用自己的邮箱收验证码和订阅，别再占用你的主邮箱 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/daily/2026-10-20-bot-own-email"}]]},"headers":[],"relativePath":"daily/2026-10-20-bot-own-email.md","filePath":"daily/2026-10-20-bot-own-email.md","lastUpdated":1792499451000}'),s={name:"daily/2026-10-20-bot-own-email.md"};function i(l,t,r,d,p,c){return e(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="让-bot-用自己的邮箱收验证码和订阅-别再占用你的主邮箱" tabindex="-1">让 Bot 用自己的邮箱收验证码和订阅，别再占用你的主邮箱 <a class="header-anchor" href="#让-bot-用自己的邮箱收验证码和订阅-别再占用你的主邮箱" aria-label="Permalink to &quot;让 Bot 用自己的邮箱收验证码和订阅，别再占用你的主邮箱&quot;">​</a></h1><p>从 0.70.2 起，Bot 可以<strong>申请一个属于自己的邮箱地址</strong>并在那里收信；0.71.2 又加上了<strong>带标签的地址</strong>。这件事看起来小，用好了能省很多麻烦。</p><h2 id="它能做什么、不能做什么" tabindex="-1">它能做什么、不能做什么 <a class="header-anchor" href="#它能做什么、不能做什么" aria-label="Permalink to &quot;它能做什么、不能做什么&quot;">​</a></h2><ul><li><strong>能收信</strong>：网站发来的验证码、登录链接，Bot 可以直接从自己的收件箱里读，不用再来问你。</li><li><strong>发信要你批</strong>：从这个地址发出的邮件默认先变成草稿卡片，你点了发送才会发出。</li><li><strong>能分流</strong>：<code>名字+标签@</code> 形式的地址都能收，<strong>挂在某个标签上的例程只处理发到这个标签的邮件</strong>。</li><li>如果你的团队或账号关闭了这个功能，Bot 会直接告诉你，而不是说&quot;暂时出了问题&quot;。</li></ul><h2 id="第一步-让-bot-申请地址" tabindex="-1">第一步：让 Bot 申请地址 <a class="header-anchor" href="#第一步-让-bot-申请地址" aria-label="Permalink to &quot;第一步：让 Bot 申请地址&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>给你申请一个自己的邮箱地址，用户名用 wangbot-research。</span></span>
<span class="line"><span>申请前先告诉我完整地址让我确认。</span></span></code></pre></div><p>申请前会有确认卡片，地址一旦申请就不能改，名字想好再定。</p><h2 id="第二步-按用途分标签" tabindex="-1">第二步：按用途分标签 <a class="header-anchor" href="#第二步-按用途分标签" aria-label="Permalink to &quot;第二步：按用途分标签&quot;">​</a></h2><table tabindex="0"><thead><tr><th>地址</th><th>用途</th></tr></thead><tbody><tr><td><code>名字+signup@…</code></td><td>注册新网站、收验证码</td></tr><tr><td><code>名字+news@…</code></td><td>订阅行业周报、Newsletter</td></tr><tr><td><code>名字+receipt@…</code></td><td>让商家把电子发票、收据发到这里</td></tr></tbody></table><h2 id="第三步-给标签挂例程" tabindex="-1">第三步：给标签挂例程 <a class="header-anchor" href="#第三步-给标签挂例程" aria-label="Permalink to &quot;第三步：给标签挂例程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>建一个例程：每当 +news 地址收到新邮件，</span></span>
<span class="line"><span>提炼成 3 条以内要点（每条附原文链接），每天 21:00 汇总发我一次。</span></span>
<span class="line"><span>不要回复任何邮件，不要点退订链接。</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>建一个例程：+receipt 地址每收到一张发票或收据，</span></span>
<span class="line"><span>把日期、商户、金额、类别追加到&quot;10 月开支&quot;表格里；读不出的金额标红，不要猜。</span></span></code></pre></div><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">不要拿它当安全隔离</p><p>所有 Bot 共用一台云电脑，文件和浏览器登录是共享的。Bot 自己的邮箱适合&quot;分流杂事&quot;，不适合存放敏感账号的找回邮件。</p></div><ul><li>用它注册的网站账号，密码依然通过安全表单或接管输入，不要在聊天里发。</li><li>不想每封都审？可以对某个 Bot 选「Disable drafts」让它直接发，但<strong>只建议用在只给你自己发信的 Bot 上</strong>。详见<a href="/basics/drafts-first">邮件和消息为什么先出草稿</a>。</li></ul>`,15)])])}const m=a(s,[["render",i]]);export{g as __pageData,m as default};
